def language_code(language: str) -> str:
    """Return the short locale code used by APIs and language-sensitive helpers."""
    return LANGUAGE_CODES.get(language, "en")


def language_name(value: str) -> str:
    """Accept either a displayed language name or its short locale code."""
    return LANGUAGE_NAMES.get(value, value if value in LANGUAGES else "English")


def translate(text: str, language: str) -> str:
    """Translate known interface phrases; preserve unlisted factual/source text."""
    if language == "English" or text not in PHRASES:
        return text
    return PHRASES[text][LANGUAGES.index(language) - 1]


def translate_mapping(values: dict, language: str) -> dict:
    """Translate known strings and option lists in a page's English copy mapping."""
    if language == "English":
        return values
    return {
        key: [translate(item, language) for item in value]
        if isinstance(value, list)
        else {item_key: translate(item_value, language) for item_key, item_value in value.items()}
        if isinstance(value, dict)
        else translate(value, language) if isinstance(value, str)
        else value
        for key, value in values.items()
    }
